// ThinkingLevel 统一思考强度档位（手动开关式）。不设置该键 = 开关关闭，不传任何 thinking 字段，
// 沿用模型/网关默认（注意：默认开思考的推理模型在不设置该键时仍会思考，此为 by design）。
// off = 开关开启且显式关闭思考，映射为各协议原生关闭参数
// （OpenAI reasoning_effort "none" / Anthropic thinking disabled / Gemini thinkingBudget 0），
// 该参数的模型兼容性由用户自行保证，LinguaFlow 不做模型能力校验。
// minimal = 开关开启并选择最低档位，映射为各协议原生最低档参数
// （OpenAI reasoning_effort "minimal" / Anthropic budget_tokens ≈ max_tokens 的 12.5% / Gemini ThinkingLevel "MINIMAL"）。
// minimal/low/medium/high = 开关开启并选择档位，由各适配层映射为厂商原生参数。仅对支持推理的模型生效。
type ThinkingLevel string

// TranslateRoundConfig defines model for TranslateRoundConfig.
type TranslateRoundConfig struct {
	// BatchSize 待译段落数上限（不计上下文段）；0=不限制，与 max_words_per_batch 至少填一项
	BatchSize *int `json:"batch_size,omitempty"`

	// FallbackShrink 池缩比系数（合法域 (0,1]）：池 N 的批次约束 = floor(orig × shrink^N)。
	// 1.0 = 不缩（多池同尺寸重切）；(0,1) = 每池缩小。
	// 0 非法（不缩请用 1.0）；必填，省略/零值会被后端拒绝（不规范化）。
	// 池数量由 retry.max_attempts+1 决定。
	FallbackShrink float32 `json:"fallback_shrink"`

	// MaxWordsPerBatch 字词数上限（计入上下文段）；0=不限制，与 batch_size 至少填一项。纯行数模式（此项与 context.max_chars 均为 0）下上下文体积不受约束
	MaxWordsPerBatch *int `json:"max_words_per_batch,omitempty"`

	// PromptTemplateId 翻译提示词模板 ID
	PromptTemplateId *int         `json:"prompt_template_id,omitempty"`
	Retry            *RetryConfig `json:"retry,omitempty"`

	// SegmentFilter 翻译轮次段落过滤配置，决定处理哪些翻译状态的段落。
	SegmentFilter *TranslateSegmentFilterConfig `json:"segment_filter,omitempty"`
}

// TranslateSegmentFilterConfig 翻译轮次段落过滤配置，决定处理哪些翻译状态的段落。
type TranslateSegmentFilterConfig struct {
	// StatusFilter - pending_only: 仅处理 pending 和 rejected 状态的段落（默认，等同旧 skip_translated）
	// - skip_approved: 处理除 approved 外的所有状态（等同旧 overwrite_unapproved）
	// - all: 处理所有状态的段落（等同旧 overwrite_all）
	StatusFilter *TranslateSegmentFilterConfigStatusFilter `json:"status_filter,omitempty"`
}

// TranslateSegmentFilterConfigStatusFilter - pending_only: 仅处理 pending 和 rejected 状态的段落（默认，等同旧 skip_translated）
// - skip_approved: 处理除 approved 外的所有状态（等同旧 overwrite_unapproved）
// - all: 处理所有状态的段落（等同旧 overwrite_all）
type TranslateSegmentFilterConfigStatusFilter string

// TranslationBatchDiagnostic defines model for TranslationBatchDiagnostic.
type TranslationBatchDiagnostic struct {
	// AddedGlossary 本批次抽取/自举新增的术语（仅写入内存 overlay）
	AddedGlossary *[]GlossaryEntry `json:"added_glossary,omitempty"`

	// Attempt 批次重试序号（0 起始）
	Attempt      *int    `json:"attempt,omitempty"`
	BackendName  *string `json:"backend_name,omitempty"`
	DurationMs   *int    `json:"duration_ms,omitempty"`
	ErrorMessage *string `json:"error_message,omitempty"`

	// ErrorType backend_error | parse_error | placeholder_error | render_error
	ErrorType    *string `json:"error_type,omitempty"`
	HttpStatus   *int    `json:"http_status,omitempty"`
	InputTokens  *int    `json:"input_tokens,omitempty"`
	OutputTokens *int    `json:"output_tokens,omitempty"`

	// Repaired 响应解析修复算子链（如 json.close-braces、json.truncation-salvage），按应用顺序记录
	Repaired *[]string `json:"repaired,omitempty"`

	// Request 发送给后端的请求诊断（不含 provider headers、API key 或 backend options）
	Request *struct {
		// JsonSchema 请求所附 JSON schema（按需）
		JsonSchema *map[string]interface{} `json:"json_schema,omitempty"`

		// ResponseFormat none | json_schema | json_object | ""（后端默认）
		ResponseFormat        *string `json:"response_format,omitempty"`
		SystemPrompt          *string `json:"system_prompt,omitempty"`
		SystemPromptLength    *int    `json:"system_prompt_length,omitempty"`
		SystemPromptTruncated *bool   `json:"system_prompt_truncated,omitempty"`
		UserMessage           *string `json:"user_message,omitempty"`
		UserMessageLength     *int    `json:"user_message_length,omitempty"`
		UserMessageTruncated  *bool   `json:"user_message_truncated,omitempty"`
	} `json:"request,omitempty"`
	Response *struct {
		// Content 后端原始文本响应
		Content          *string `json:"content,omitempty"`
		ContentLength    *int    `json:"content_length,omitempty"`
		ContentTruncated *bool   `json:"content_truncated,omitempty"`
	} `json:"response,omitempty"`
	RoundIndex   *int `json:"round_index,omitempty"`
	SegmentCount *int `json:"segment_count,omitempty"`

	// SegmentIds 文档段 ID（doc.Segments[idx].ID，对 Web 文档为 segment_index 字符串）
	SegmentIds      *[]string `json:"segment_ids,omitempty"`
	ShrinkAttempted *bool     `json:"shrink_attempted,omitempty"`

	// Stage extract | translate | adjudicate | semantic_qa | revise | ruby_retry
	Stage         string                           `json:"stage"`
	Status        TranslationBatchDiagnosticStatus `json:"status"`
	TriedBackends *[]string                        `json:"tried_backends,omitempty"`

	// Truncated 后端响应因输出 token 上限被截断（finish_reason=MAX_TOKENS/length、stop_reason=max_tokens）；部分文本仍有效，已由修复链抢救完整前缀，缺失条目走重跑通道
	Truncated    *bool            `json:"truncated,omitempty"`
	UsedGlossary *[]GlossaryEntry `json:"used_glossary,omitempty"`
}

